package com.example.splitstory;
import java.io.*;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.cert.*;import java.util.*;
/** Portable signing container, using JCA primitives. No Android APIs; host round-trip tested. */
final class CreatorKeys {
final PrivateKey key;final X509Certificate cert;CreatorKeys(PrivateKey k,X509Certificate c){key=k;cert=c;}
static CreatorKeys generate()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);KeyPair p=g.generateKeyPair();byte[] algorithm=seq(oid(new byte[]{0x2a,(byte)0x86,0x48,(byte)0x86,(byte)0xf7,0x0d,1,1,11}),tag(5,new byte[0]));byte[] name=seq(tag(0x31,seq(oid(new byte[]{0x55,4,3}),tag(0x0c,"Event Game Creator".getBytes(StandardCharsets.UTF_8)))));byte[] dates=seq(tag(0x18,"20200101000000Z".getBytes(StandardCharsets.US_ASCII)),tag(0x18,"21000101000000Z".getBytes(StandardCharsets.US_ASCII)));byte[] serial=new BigInteger(120,new SecureRandom()).add(BigInteger.ONE).toByteArray();byte[] tbs=seq(tag(0xa0,tag(2,new byte[]{2})),tag(2,serial),algorithm,name,dates,name,p.getPublic().getEncoded());Signature s=Signature.getInstance("SHA256withRSA");s.initSign(p.getPrivate());s.update(tbs);byte[] sig=s.sign(),bit=new byte[sig.length+1];System.arraycopy(sig,0,bit,1,sig.length);X509Certificate c=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(seq(tbs,algorithm,tag(3,bit))));c.verify(p.getPublic());return new CreatorKeys(p.getPrivate(),c);}
byte[] encode()throws Exception{byte[] privateKey=key.getEncoded(),certificate=cert.getEncoded();if(privateKey==null)throw new IOException("이 서명은 기기 밖으로 백업할 수 없습니다.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(0x45564b31);out.writeInt(privateKey.length);out.write(privateKey);out.writeInt(certificate.length);out.write(certificate);}return bytes.toByteArray();}
static CreatorKeys decode(byte[] bytes)throws Exception{if(bytes.length>20000)throw new IOException("배포 키 크기");DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes));if(in.readInt()!=0x45564b31)throw new IOException("배포 키 형식");int n=in.readInt();if(n<1||n>10000)throw new IOException("개인키 형식");byte[] privateKey=new byte[n];in.readFully(privateKey);n=in.readInt();if(n<1||n>10000||n!=in.available())throw new IOException("인증서 형식");byte[] certificate=new byte[n];in.readFully(certificate);PrivateKey k=KeyFactory.getInstance("RSA").generatePrivate(new java.security.spec.PKCS8EncodedKeySpec(privateKey));X509Certificate c=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(certificate));Signature s=Signature.getInstance("SHA256withRSA");s.initSign(k);s.update(new byte[]{1,2,3});byte[] signed=s.sign();s.initVerify(c);s.update(new byte[]{1,2,3});if(!s.verify(signed))throw new IOException("배포 키 일치 확인 실패");return new CreatorKeys(k,c);}
static byte[] oid(byte[] b)throws IOException{return tag(6,b);}static byte[] seq(byte[]...a)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();for(byte[] v:a)b.write(v);return tag(0x30,b.toByteArray());}static byte[] tag(int tag,byte[] value)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();b.write(tag);int n=value.length;if(n<128)b.write(n);else{int len=n>65535?3:n>255?2:1;b.write(128|len);for(int i=len-1;i>=0;i--)b.write(n>>(8*i));}b.write(value);return b.toByteArray();}
}
